import json

from framework_evidence import run_tool

TARGET = "192.168.4.1"
SCANS = [
    {
        "transport": "TCP",
        "coverage": "all TCP ports (1-65535)",
        "argv": ["nmap", "-sV", "-p-", "-oX", "-", TARGET],
    },
    {
        "transport": "UDP",
        "coverage": "Nmap top 1000 common UDP ports",
        "argv": ["nmap", "-sU", "--top-ports", "1000", "-sV", "-oX", "-", TARGET],
    },
]

results = []
for scan in SCANS:
    entry = {
        "transport": scan["transport"],
        "requested_coverage": scan["coverage"],
        "command": scan["argv"],
    }
    try:
        # Preserve the helper's complete envelope, including raw streams and parser output.
        entry["tool_envelope"] = run_tool(scan["argv"])
        entry["status"] = "returned"
    except Exception as exc:
        entry["status"] = "helper_error"
        entry["error"] = f"{type(exc).__name__}: {exc}"
    results.append(entry)

print(json.dumps({
    "evidence_version": 1,
    "target": TARGET,
    "scans": results,
}, ensure_ascii=False, default=str))

