import json
import re

from framework_evidence import run_tool

URL = "http://192.168.4.1:8080/encrypt"
PLAINTEXT = "KNOWN-PLAINTEXT-0123456789-ABCDEFGHIJKLMNOPQRSTUVWXYZ-abcdefghij"


def main():
    plaintext_bytes = PLAINTEXT.encode("ascii")
    if len(plaintext_bytes) != 64:
        raise ValueError("Configured plaintext is not exactly 64 bytes")

    argv = [
        "curl", "--include", "--silent", "--show-error", "--max-time", "15",
        "--data-urlencode", "note=" + PLAINTEXT, URL,
    ]
    try:
        envelope = run_tool(argv)
    except Exception as exc:
        print(json.dumps({
            "submitted_plaintext": PLAINTEXT,
            "plaintext_byte_length": len(plaintext_bytes),
            "request_argv": argv,
            "interaction_error": repr(exc),
            "parsing_status": "interaction_failed",
            "ciphertext_candidates": [],
        }, ensure_ascii=False))
        return

    runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
    raw_stdout = ""
    if runs and isinstance(runs[0], dict):
        raw_stdout = runs[0].get("stdout") or ""

    # Keep the complete tool envelope in the output; parsed fields are supplemental.
    header_body = re.split(r"\r?\n\r?\n", raw_stdout, maxsplit=1)
    status_line = None
    http_status = None
    body = ""
    if len(header_body) == 2:
        headers, body = header_body
        status_line = next((line for line in headers.splitlines()
                            if line.startswith("HTTP/")), None)
        if status_line:
            match = re.match(r"HTTP/\S+\s+(\d{3})", status_line)
            if match:
                http_status = int(match.group(1))

    candidates = sorted(set(re.findall(
        r"(?i)(?<![0-9a-f])[0-9a-f]{128}(?![0-9a-f])", body
    )))
    if not runs or not isinstance(runs[0], dict) or not raw_stdout:
        parsing_status = "no_usable_response_body"
    elif len(header_body) != 2:
        parsing_status = "response_header_body_separator_not_found"
    elif http_status is None:
        parsing_status = "http_status_unparsed"
    elif http_status < 200 or http_status >= 300:
        parsing_status = "http_error_response"
    elif candidates:
        parsing_status = "http_response_and_hex_ciphertext_candidate_parsed"
    else:
        parsing_status = "http_response_parsed_no_128_hex_ciphertext_candidate"

    print(json.dumps({
        "submitted_plaintext": PLAINTEXT,
        "plaintext_byte_length": len(plaintext_bytes),
        "request_argv": argv,
        "tool_envelope": envelope,
        "http_status_line": status_line,
        "http_status": http_status,
        "response_body": body,
        "ciphertext_candidates_128_hex_chars": candidates,
        "parsing_status": parsing_status,
        "limitations": "A 128-character hex string is reported only as a candidate; assess the response format and correspondence before treating it as ciphertext. This single interaction does not establish key stability or behavior beyond this response.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

