import json
import re
import sys

from framework_evidence import run_tool

BASE = "http://192.168.4.1:8080"
TIMEOUT = "15"
# 9-byte prefix plus 55 ASCII bytes = exactly 64 bytes.
PLAINTEXT = "READBACK-" + ("A" * 55)


def request(label, argv):
    try:
        envelope = run_tool(argv)
        return {"label": label, "requested_argv": argv, "tool_envelope": envelope}
    except Exception as exc:
        return {"label": label, "requested_argv": argv, "tool_error": repr(exc)}


def stdout_from(result):
    envelope = result.get("tool_envelope")
    if not isinstance(envelope, dict):
        return None
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return None
    first = runs[0]
    if not isinstance(first, dict) or not isinstance(first.get("stdout"), str):
        return None
    return first["stdout"]


def response_body(raw):
    if raw is None:
        return None, "tool stdout unavailable"
    match = re.search(r"HTTP/\S+\s+(\d{3})", raw)
    status = match.group(1) if match else None
    parts = re.split(r"\r?\n\r?\n", raw, maxsplit=1)
    if len(parts) != 2:
        return status, "could not locate HTTP header/body separator"
    return status, parts[1]


def note_ciphertexts(body):
    if body is None:
        return None, "response body unavailable"
    # Exclude the explicitly labelled encrypted_flag so it cannot be mistaken
    # for a newly stored note ciphertext.
    without_flag = re.sub(
        r"encrypted_flag\s*:\s*[0-9a-fA-F]{128}", " ", body, flags=re.IGNORECASE
    )
    values = re.findall(r"(?<![0-9a-fA-F])[0-9a-fA-F]{128}(?![0-9a-fA-F])", without_flag)
    return values, "parsed 128-hex values outside an encrypted_flag field"


curl_base = ["curl", "--include", "--silent", "--show-error", "--max-time", TIMEOUT]
before = request("notes_before_submission", curl_base + [BASE + "/show_encrypted_notes"])
post = request(
    "submit_distinctive_64_byte_plaintext",
    curl_base + ["--data-urlencode", "note=" + PLAINTEXT, BASE + "/encrypt"],
)
after = request("notes_after_submission", curl_base + [BASE + "/show_encrypted_notes"])

before_status, before_body = response_body(stdout_from(before))
after_status, after_body = response_body(stdout_from(after))
before_values, before_parse = note_ciphertexts(before_body if isinstance(before_body, str) else None)
after_values, after_parse = note_ciphertexts(after_body if isinstance(after_body, str) else None)

comparison = {"status": "not_comparable", "new_ciphertext_candidates": [], "matching_basis": ""}
if before_values is not None and after_values is not None:
    before_counts = {}
    for value in before_values:
        before_counts[value] = before_counts.get(value, 0) + 1
    new_values = []
    for value in after_values:
        if before_counts.get(value, 0):
            before_counts[value] -= 1
        else:
            new_values.append(value)
    comparison["new_ciphertext_candidates"] = new_values
    if len(new_values) == 1:
        comparison["status"] = "one_new_candidate_temporally_associated"
        comparison["matching_basis"] = (
            "The 128-hex value was absent from the pre-submission notes view and appeared "
            "in the post-submission view after this controlled submission. This is a "
            "temporal record-matching basis, not proof of key reuse."
        )
    elif len(new_values) > 1:
        comparison["status"] = "ambiguous_multiple_new_candidates"
        comparison["matching_basis"] = "Multiple note ciphertext candidates appeared after submission; no unique match is established."
    else:
        comparison["status"] = "no_new_candidate_observed"
        comparison["matching_basis"] = "No additional 128-hex non-flag candidate was found in the post-submission view."

output = {
    "submitted_plaintext": PLAINTEXT,
    "submitted_plaintext_utf8_byte_length": len(PLAINTEXT.encode("utf-8")),
    "requests_and_raw_tool_responses": [before, post, after],
    "parsing": {
        "before_http_status": before_status,
        "before_notes_view": before_parse,
        "before_candidate_count": None if before_values is None else len(before_values),
        "after_http_status": after_status,
        "after_notes_view": after_parse,
        "after_candidate_count": None if after_values is None else len(after_values),
        "comparison": comparison,
        "limitation": "A temporal difference associates a newly exposed record with the controlled submission but does not independently prove service internals or key consistency. HTTP success and parser success are not themselves evidence of a usable pair."
    }
}
print(json.dumps(output, ensure_ascii=False, sort_keys=True))

