import collections
import html
import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"status": "error", "error": "Could not import framework_evidence.run_tool", "detail": str(exc)}))
    sys.exit(1)

BASE = "http://192.168.4.1:8080"
SNAPSHOT_URL = BASE + "/show_encrypted_notes"
ENCRYPT_URL = BASE + "/encrypt"
PROBES = [
    "PROBE-A-" + "A" * 56,
    "PROBE-B-" + "B" * 56,
]

for text in PROBES:
    if len(text.encode("utf-8")) != 64:
        raise AssertionError("Probe plaintext is not exactly 64 UTF-8 bytes")


def request(argv):
    try:
        envelope = run_tool(argv)
        return envelope, None
    except Exception as exc:
        return None, str(exc)


def tool_result(envelope):
    """Return stdout, exit code and status without discarding the original envelope."""
    if not isinstance(envelope, dict):
        return "", None, "unexpected_envelope_type"
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return "", None, "missing_tool_runs"
    run = runs[0]
    if not isinstance(run, dict):
        return "", None, "malformed_tool_run"
    return run.get("stdout", ""), run.get("exit_code"), run.get("status")


def ciphertexts_from_snapshot(stdout):
    # The response is HTML; unescape it before extracting the displayed hex values.
    body = stdout.split("\r\n\r\n", 1)[-1]
    if body == stdout:
        body = stdout.split("\n\n", 1)[-1]
    text = html.unescape(body)
    return re.findall(r"encrypted\s+text\s+\d+\s*:\s*([0-9a-fA-F]+)", text, re.IGNORECASE)


def capture_snapshot():
    argv = ["curl", "--include", "--silent", "--show-error", "--max-time", "15", SNAPSHOT_URL]
    envelope, error = request(argv)
    if error:
        return {"requested_argv": argv, "tool_envelope": None, "request_error": error, "ciphertexts": []}
    stdout, exit_code, status = tool_result(envelope)
    return {
        "requested_argv": argv,
        "tool_envelope": envelope,
        "exit_code": exit_code,
        "tool_status": status,
        "ciphertexts": ciphertexts_from_snapshot(stdout),
    }


def new_ciphertexts(before, after):
    before_counts = collections.Counter(before)
    added = []
    for value in after:
        if before_counts[value]:
            before_counts[value] -= 1
        else:
            added.append(value)
    return added


records = []
for index, plaintext in enumerate(PROBES, 1):
    before = capture_snapshot()
    submit_argv = [
        "curl", "--include", "--silent", "--show-error", "--max-time", "15",
        "--data-urlencode", "note=" + plaintext, ENCRYPT_URL,
    ]
    submit_envelope, submit_error = request(submit_argv)
    if submit_error:
        submit_stdout, submit_exit, submit_status = "", None, "request_error"
    else:
        submit_stdout, submit_exit, submit_status = tool_result(submit_envelope)
    after = capture_snapshot()
    added = new_ciphertexts(before["ciphertexts"], after["ciphertexts"])
    associated = added[0] if len(added) == 1 else None
    try:
        cipher_bytes = bytes.fromhex(associated) if associated is not None else None
        length_ok = cipher_bytes is not None and len(cipher_bytes) == 64
    except ValueError:
        cipher_bytes = None
        length_ok = False
    records.append({
        "probe_number": index,
        "plaintext": plaintext,
        "plaintext_utf8_byte_length": len(plaintext.encode("utf-8")),
        "before_snapshot": before,
        "submission": {
            "requested_argv": submit_argv,
            "tool_envelope": submit_envelope,
            "request_error": submit_error,
            "exit_code": submit_exit,
            "tool_status": submit_status,
            "response_excerpt": submit_stdout[-1000:],
        },
        "after_snapshot": after,
        "new_ciphertexts_in_snapshot_difference": added,
        "associated_ciphertext_hex": associated,
        "ciphertext_byte_length": len(cipher_bytes) if cipher_bytes is not None else None,
        "association_unambiguous": len(added) == 1,
        "ciphertext_length_is_64_bytes": length_ok,
    })

result = {
    "target": BASE,
    "operation": "two controlled known-plaintext XOR probes",
    "pairs": records,
    "candidate_key_hex": None,
    "key_consistency": None,
    "conclusion": "inconclusive: both pairs must have one unambiguous, valid 64-byte ciphertext",
}

if all(r["association_unambiguous"] and r["ciphertext_length_is_64_bytes"] for r in records):
    p1 = PROBES[0].encode("utf-8")
    p2 = PROBES[1].encode("utf-8")
    c1 = bytes.fromhex(records[0]["associated_ciphertext_hex"])
    c2 = bytes.fromhex(records[1]["associated_ciphertext_hex"])
    key = bytes(a ^ b for a, b in zip(p1, c1))
    reproduced_first = bytes(a ^ b for a, b in zip(p1, key))
    reproduced_second = bytes(a ^ b for a, b in zip(p2, key))
    first_match = reproduced_first == c1
    second_match = reproduced_second == c2
    result["candidate_key_hex"] = key.hex()
    result["key_consistency"] = {
        "first_pair_reproduces_ciphertext": first_match,
        "second_pair_reproduces_ciphertext_byte_for_byte": second_match,
        "both_pairs_match": first_match and second_match,
    }
    result["conclusion"] = "candidate key consistent with both observed pairs" if first_match and second_match else "pairs inconsistent with one shared XOR key"

print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))

