import base64
import json
import re
import urllib.error
import urllib.request

BASE = "http://192.168.4.1:8080"


def request(path):
    url = urllib.request.urljoin(BASE + "/", path.lstrip("/"))
    req = urllib.request.Request(url, headers={"User-Agent": "flag-material-evidence/1.0", "Accept": "*/*"}, method="GET")
    try:
        response = urllib.request.urlopen(req, timeout=10)
        status = response.status
        final_url = response.geturl()
        headers = list(response.headers.items())
        body = response.read()
    except urllib.error.HTTPError as exc:
        status = exc.code
        final_url = exc.geturl()
        headers = list(exc.headers.items()) if exc.headers else []
        body = exc.read()
    except Exception as exc:
        return {"requested_url": url, "error": type(exc).__name__ + ": " + str(exc)}

    record = {
        "requested_url": url,
        "final_url": final_url,
        "status": status,
        "headers": headers,
        "body_base64": base64.b64encode(body).decode("ascii"),
    }
    try:
        record["body_utf8"] = body.decode("utf-8")
    except UnicodeDecodeError:
        record["body_utf8"] = None
    try:
        parsed = json.loads(body.decode("utf-8"))
        record["parsed_json"] = parsed
        record["json_parse_status"] = "success"
        record["explicit_material_fields"] = find_material_fields(parsed)
    except (UnicodeDecodeError, json.JSONDecodeError):
        record["json_parse_status"] = "not_json_or_not_utf8"
    return record


def find_material_fields(value, path="$", found=None):
    if found is None:
        found = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = path + "." + str(key)
            if re.search(r"flag|cipher|encrypted|stored.?note", str(key), re.I):
                found.append({"path": child_path, "value": child})
            find_material_fields(child, child_path, found)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            find_material_fields(child, path + "[" + str(index) + "]", found)
    return found


# The root response is retained as service context; /notes is the directly relevant
# readback resource indicated by the recorded encrypted-notes interaction.
observations = [request("/"), request("/notes")]
print(json.dumps({
    "target": BASE,
    "purpose": "Retrieve and preserve service responses relevant to stored encrypted notes/flag material",
    "observations": observations,
    "interpretation": "Field names and response content are observations only. Encrypted material is associated with the stored flag only when the service response or record context makes that relationship explicit; otherwise retrieval remains inconclusive."
}, ensure_ascii=False))

