import base64
import html
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.4.1:8080"
ORIGIN = urllib.parse.urlsplit(BASE).netloc


class ResourceParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a" and attrs.get("href"):
            self.references.append((attrs["href"], "link"))
        elif tag == "form":
            method = attrs.get("method", "get").lower()
            action = attrs.get("action", "")
            if method == "get" and action:
                self.references.append((action, "GET form action"))


def resolve_same_origin(reference):
    absolute = urllib.parse.urljoin(BASE + "/", reference)
    parsed = urllib.parse.urlsplit(absolute)
    if parsed.scheme not in ("http", "https") or parsed.netloc != ORIGIN:
        return None
    return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path or "/", parsed.query, ""))


def declared_get_routes(text):
    # Inspect explicit Flask-style route declarations, but do not invent route names.
    routes = []
    pattern = re.compile(
        r"@\w+\.(?:route|get)\(\s*(['\"])(.*?)\1([^)]*)\)", re.S
    )
    for match in pattern.finditer(text):
        path, options = match.group(2), match.group(3)
        if "<" in path or ">" in path:
            continue
        methods_match = re.search(r"methods\s*=\s*\[([^]]*)\]", options, re.I | re.S)
        methods = re.findall(r"['\"](GET|POST|PUT|PATCH|DELETE|OPTIONS|HEAD)['\"]", methods_match.group(1), re.I) if methods_match else ["GET"]
        if any(method.upper() == "GET" for method in methods):
            routes.append(path)
    return routes


def fetch(url):
    request = urllib.request.Request(url, headers={"User-Agent": "service-resource-observer/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            body = response.read()
            return {
                "requested_url": url,
                "final_url": response.geturl(),
                "status": response.status,
                "headers": list(response.headers.items()),
                "body_base64": base64.b64encode(body).decode("ascii"),
                "body_utf8": body.decode("utf-8", errors="replace"),
                "error": None,
            }
    except urllib.error.HTTPError as exc:
        body = exc.read()
        return {
            "requested_url": url,
            "final_url": exc.geturl(),
            "status": exc.code,
            "headers": list(exc.headers.items()) if exc.headers else [],
            "body_base64": base64.b64encode(body).decode("ascii"),
            "body_utf8": body.decode("utf-8", errors="replace"),
            "error": "HTTP error response",
        }
    except Exception as exc:
        return {"requested_url": url, "status": None, "error": repr(exc)}


def main():
    queue = [(BASE + "/", "previously observed service home page")]
    seen = set()
    observations = []
    while queue:
        url, disclosed_by = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        result = fetch(url)
        result["disclosed_by"] = disclosed_by
        observations.append(result)
        body = result.get("body_utf8", "")
        if not body:
            continue
        parser = ResourceParser()
        try:
            parser.feed(body)
        except Exception:
            pass
        references = list(parser.references)
        decoded = html.unescape(body)
        references.extend((route, "GET route declared in service response") for route in declared_get_routes(decoded))
        for reference, source in references:
            target = resolve_same_origin(reference)
            if target and target not in seen and all(target != queued[0] for queued in queue):
                queue.append((target, source + " from " + url))

    print(json.dumps({
        "target": BASE,
        "purpose": "Examine service-disclosed same-origin resources for encrypted material and its record context",
        "requests_made": len(observations),
        "observations": observations,
        "coverage_note": "Only the home page and same-origin links, GET form actions, and explicit GET routes disclosed in retrieved responses were examined. No form was submitted and no undisclosed path was probed.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

