import base64
import json
import sys
import urllib.error
import urllib.request

URL = "http://192.168.4.1:8080/show_encrypted_notes"


def find_labeled_values(value, path="$", matches=None):
    if matches is None:
        matches = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = path + "." + str(key)
            if key == "encrypted_flag":
                matches.append({"path": child_path, "value": child})
            find_labeled_values(child, child_path, matches)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            find_labeled_values(child, path + "[" + str(index) + "]", matches)
    return matches


request = urllib.request.Request(
    URL,
    headers={"Accept": "application/json, text/plain, */*", "User-Agent": "Python-urllib encrypted-notes evidence retrieval"},
    method="GET",
)
result = {
    "request_url": URL,
    "request_method": "GET",
    "response_received": False,
    "body_read_to_eof": False,
}
response = None
try:
    try:
        response = urllib.request.urlopen(request, timeout=20)
    except urllib.error.HTTPError as exc:
        # HTTP error responses can still contain the resource's response body.
        response = exc
        result["http_error"] = str(exc)
    result["response_received"] = True
    result["status"] = response.code
    result["response_url"] = response.geturl()
    result["headers"] = dict(response.headers.items())
    try:
        body = response.read()
        result["body_read_to_eof"] = True
        result["body_byte_length"] = len(body)
        result["body_base64"] = base64.b64encode(body).decode("ascii")
        try:
            text = body.decode("utf-8")
            result["body_utf8"] = text
            try:
                parsed = json.loads(text)
                result["json_parse"] = "success"
                result["parsed_json"] = parsed
                result["encrypted_flag_matches"] = find_labeled_values(parsed)
                if isinstance(parsed, dict):
                    notes = parsed.get("enc_notes")
                    if isinstance(notes, list) and notes:
                        result["enc_notes_0"] = notes[0]
                    elif isinstance(notes, list):
                        result["enc_notes_0"] = None
                        result["enc_notes"] = "present but empty"
                    else:
                        result["enc_notes"] = "not a list at the top level or absent"
                else:
                    result["enc_notes"] = "top-level JSON value is not an object"
            except json.JSONDecodeError as exc:
                result["json_parse"] = "failed"
                result["json_parse_error"] = str(exc)
        except UnicodeDecodeError as exc:
            result["body_utf8"] = None
            result["utf8_decode_error"] = str(exc)
            result["json_parse"] = "not attempted: response body is not valid UTF-8"
        content_length = response.headers.get("Content-Length")
        if content_length is not None:
            try:
                result["content_length_header"] = int(content_length)
                result["content_length_matches_body"] = int(content_length) == len(body)
            except ValueError:
                result["content_length_header"] = content_length
                result["content_length_matches_body"] = None
    except Exception as exc:
        result["body_read_error"] = type(exc).__name__ + ": " + str(exc)
except Exception as exc:
    result["request_error"] = type(exc).__name__ + ": " + str(exc)
finally:
    if response is not None:
        response.close()

print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))

