#!/usr/bin/env python3
import base64
import binascii
import json
import re
import sys
import urllib.error
import urllib.request

BASE = "http://192.168.4.1:8080"
KEY_HEX = "ebd2df76aac328081c10a48e91f848fbdf6edb15fa680ba1fec52e070a8ca81b9bc9110af8732af92bf3f39e48b0b45208a78f1b6efc691b1c991f828943d025"
TIMEOUT = 15


def fetch(path):
    url = BASE + path
    req = urllib.request.Request(url, headers={"User-Agent": "fresh-service-evidence/1.0", "Accept": "*/*"})
    try:
        response = urllib.request.urlopen(req, timeout=TIMEOUT)
        status = response.status
        headers = dict(response.headers.items())
        raw = response.read()
        response.close()
        error = ""
    except urllib.error.HTTPError as exc:
        status = exc.code
        headers = dict(exc.headers.items()) if exc.headers else {}
        raw = exc.read()
        error = "HTTP error response"
        exc.close()
    except Exception as exc:
        return {"url": url, "status": None, "complete": False, "headers": {},
                "body_base64": "", "body_text": "", "error": type(exc).__name__ + ": " + str(exc)}

    length_value = next((v for k, v in headers.items() if k.lower() == "content-length"), None)
    length_ok = True
    if length_value is not None:
        try:
            length_ok = len(raw) == int(length_value)
        except ValueError:
            length_ok = False
    complete = 200 <= status < 300 and length_ok
    return {"url": url, "status": status, "complete": complete, "headers": headers,
            "body_base64": base64.b64encode(raw).decode("ascii"),
            "body_text": raw.decode("utf-8", errors="replace"),
            "body_bytes": len(raw), "content_length_matches": length_ok,
            "error": error}


def walk_for_ciphertext(obj):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if str(key).lower() == "encrypted_flag":
                return value
        for value in obj.values():
            found = walk_for_ciphertext(value)
            if found is not None:
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = walk_for_ciphertext(value)
            if found is not None:
                return found
    return None


def extract_ciphertext(body):
    try:
        value = walk_for_ciphertext(json.loads(body.decode("utf-8")))
        if value is not None:
            return value, "JSON encrypted_flag field"
    except (UnicodeDecodeError, json.JSONDecodeError):
        pass
    text = body.decode("utf-8", errors="replace")
    match = re.search(r"encrypted_flag\s*[\"']?\s*[:=]\s*[\"']([^\"'<>\\s,}]+)", text, re.I)
    if match:
        return match.group(1), "text encrypted_flag label"
    return None, "encrypted_flag field not found"


def decode_ciphertext(value):
    if isinstance(value, list) and all(isinstance(x, int) and 0 <= x <= 255 for x in value):
        return bytes(value), "JSON byte array"
    if not isinstance(value, str):
        raise ValueError("encrypted_flag is not a string or byte array")
    token = value.strip()
    if token.lower().startswith("hex:"):
        return bytes.fromhex(token[4:].strip()), "hex"
    if token.lower().startswith("base64:"):
        return base64.b64decode(token[7:].strip(), validate=True), "base64"
    compact = re.sub(r"\s+", "", token)
    if compact.startswith("0x"):
        compact = compact[2:]
    if compact and len(compact) % 2 == 0 and re.fullmatch(r"[0-9a-fA-F]+", compact):
        return bytes.fromhex(compact), "hex"
    try:
        return base64.b64decode(compact, validate=True), "base64"
    except (binascii.Error, ValueError) as exc:
        raise ValueError("encrypted_flag is neither valid hex nor base64") from exc


def source_convention(body):
    text = body.decode("utf-8", errors="replace")
    has_pkcs7 = re.search(r"PKCS\s*#?\s*7|PKCS7", text, re.I) is not None
    byte_size = (
        re.search(r"(?:block[_ ]?size|block[_ ]?length|block)\s*[:=]\s*64\s*(?:bytes?)?\b", text, re.I)
        or re.search(r"\b64\s*[- ]?bytes?\b", text, re.I)
        or re.search(r"PKCS\s*#?\s*7\s*\(\s*512\s*\)", text, re.I)
    ) is not None
    excerpts = []
    for match in re.finditer(r"PKCS\s*#?\s*7|PKCS7|block[_ ]?size|block[_ ]?length|64\s*[- ]?bytes?|512", text, re.I):
        start, end = max(0, match.start() - 100), min(len(text), match.end() + 120)
        excerpt = text[start:end].replace("\r", " ").replace("\n", " ")
        if excerpt not in excerpts:
            excerpts.append(excerpt)
        if len(excerpts) == 8:
            break
    return {"pkcs7_explicit": has_pkcs7, "64_byte_block_explicit": byte_size,
            "supported": has_pkcs7 and byte_size, "relevant_source_excerpts": excerpts}


def main():
    flag_response = fetch("/")
    source_response = fetch("/source")
    report = {
        "endpoint": BASE,
        "responses": {"service_root": flag_response, "source": source_response},
        "ciphertext_association": {"found": False, "location": "", "encoding": "", "error": ""},
        "convention": {"supported": False, "pkcs7_explicit": False, "64_byte_block_explicit": False},
        "decryption": {"key_source": "previously validated key recorded in supplied dependency evidence",
                       "key_bytes": 64, "performed": False, "padding_valid": False, "error": ""},
        "success": False
    }
    if not flag_response.get("complete") or not source_response.get("complete"):
        report["decryption"]["error"] = "A fresh HTTP response was incomplete or unsuccessful; ciphertext and convention cannot be verified."
        print(json.dumps(report, ensure_ascii=False))
        return 1

    value, location = extract_ciphertext(base64.b64decode(flag_response["body_base64"]))
    report["ciphertext_association"]["location"] = location
    if value is None:
        report["ciphertext_association"]["error"] = "No encrypted_flag field was parsed from the fresh service-root response."
        print(json.dumps(report, ensure_ascii=False))
        return 1

    report["ciphertext_association"].update({"found": True, "value": value})
    convention = source_convention(base64.b64decode(source_response["body_base64"]))
    report["convention"] = convention
    if not convention["supported"]:
        report["decryption"]["error"] = "Fresh /source response does not explicitly establish both PKCS#7 and a 64-byte block rule."
        print(json.dumps(report, ensure_ascii=False))
        return 1

    try:
        ciphertext, encoding = decode_ciphertext(value)
        key = bytes.fromhex(KEY_HEX)
        if not ciphertext:
            raise ValueError("encrypted_flag decoded to an empty ciphertext")
        plaintext = bytes(c ^ key[i % len(key)] for i, c in enumerate(ciphertext))
        report["ciphertext_association"]["encoding"] = encoding
        report["decryption"].update({"performed": True,
                                    "ciphertext_bytes": len(ciphertext),
                                    "recovered_bytes_hex": plaintext.hex(),
                                    "recovered_bytes_length": len(plaintext)})
        if len(plaintext) % 64 != 0:
            raise ValueError("recovered byte length is not a multiple of the disclosed 64-byte block size")
        pad_len = plaintext[-1]
        if not 1 <= pad_len <= 64:
            raise ValueError("PKCS#7 final padding length is outside 1..64")
        expected = bytes([pad_len]) * pad_len
        actual = plaintext[-pad_len:]
        if actual != expected:
            raise ValueError("recovered suffix does not satisfy strict PKCS#7 byte-for-byte validation")
        logical = plaintext[:-pad_len]
        flag = logical.decode("utf-8", errors="strict")
        report["decryption"].update({"padding_valid": True, "padding_length": pad_len,
                                    "padding_hex": actual.hex(),
                                    "logical_bytes_hex": logical.hex(),
                                    "logical_utf8_valid": True})
        report["success"] = True
        print(json.dumps(report, ensure_ascii=False))
        print(flag)
        return 0
    except Exception as exc:
        report["decryption"]["error"] = type(exc).__name__ + ": " + str(exc)
        print(json.dumps(report, ensure_ascii=False))
        return 1


if __name__ == "__main__":
    sys.exit(main())

