import base64
import binascii
import html
import json
import os
import re
import sys
import urllib.error
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.4.1:8080"


class PreText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.in_pre = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "pre":
            self.in_pre = True

    def handle_endtag(self, tag):
        if tag.lower() == "pre":
            self.in_pre = False

    def handle_data(self, data):
        if self.in_pre:
            self.parts.append(data)


def fetch(path):
    request = urllib.request.Request(BASE + path, headers={"User-Agent": "flag-evidence-check/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            body = response.read()
            headers = dict(response.headers.items())
            status = response.status
            declared = headers.get("Content-Length")
            complete = declared is None or (declared.isdigit() and int(declared) == len(body))
            return {
                "url": BASE + path,
                "status": status,
                "headers": headers,
                "body_bytes": len(body),
                "content_length_matches": complete,
                "body": body,
                "error": "" if complete else "Content-Length does not match received body size",
            }
    except urllib.error.HTTPError as exc:
        body = exc.read()
        return {"url": BASE + path, "status": exc.code, "headers": dict(exc.headers.items()),
                "body_bytes": len(body), "content_length_matches": False, "body": body,
                "error": "HTTP error response"}
    except Exception as exc:
        return {"url": BASE + path, "status": None, "headers": {}, "body_bytes": 0,
                "content_length_matches": False, "body": b"", "error": repr(exc)}


def response_evidence(item):
    return {k: v for k, v in item.items() if k != "body"}


def extract_ciphertext(notes_text):
    # The service renders the labeled value as HTML; unescape before matching.
    visible = html.unescape(notes_text)
    match = re.search(r"\bencrypted_flag\s*:\s*([^<\s]+)", visible, re.IGNORECASE)
    if not match:
        raise ValueError("No ciphertext explicitly labeled encrypted_flag was found in the notes response")
    return match.group(1).strip()


def decode_ciphertext(value, source):
    # Prefer the encoding indicated by the freshly retrieved service source.
    if re.search(r"\.hex\s*\(|binascii\.hexlify|hexlify\s*\(", source, re.IGNORECASE):
        try:
            return bytes.fromhex(value), "hex"
        except ValueError:
            pass
    if re.search(r"b64encode|base64", source, re.IGNORECASE):
        try:
            return base64.b64decode(value, validate=True), "base64"
        except (binascii.Error, ValueError):
            pass
    # If source does not make encoding unambiguous, try strict encodings and
    # record which one actually parsed; never silently discard invalid bytes.
    try:
        return bytes.fromhex(value), "hex (fallback)"
    except ValueError:
        pass
    try:
        return base64.b64decode(value, validate=True), "base64 (fallback)"
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Ciphertext is neither valid hex nor strict base64") from exc


def inspect_padding_convention(source):
    compact = re.sub(r"\s+", " ", source)
    block_64 = bool(re.search(r"(?:BLOCK_SIZE|block_size|blocksize)\s*=\s*64\b", compact, re.I)) or bool(
        re.search(r"\bpad\s*\([^)]*,\s*64\s*\)", compact, re.I)
    )
    pkcs7 = bool(re.search(r"PKCS\s*#?\s*7|Crypto\.Util\.Padding|from\s+.*Padding\s+import\s+pad", compact, re.I))
    # PyCryptodome's pad(data, block_size) defaults to PKCS#7 when style is
    # omitted. Require evidence of that padding API and a 64-byte argument.
    padding_api = bool(re.search(r"\bpad\s*\(", compact))
    pkcs7_supported = pkcs7 or (padding_api and "Crypto.Util.Padding" in compact)
    xor = bool(re.search(r"\^", source))
    return {
        "block_size_64_supported": block_64,
        "pkcs7_supported": pkcs7_supported,
        "padding_api_present": padding_api,
        "xor_operator_present": xor,
        "source_excerpt": " ".join(
            line.strip() for line in source.splitlines()
            if re.search(r"BLOCK_SIZE|block_size|pad\s*\(|PKCS|Padding|\^", line, re.I)
        )[:1600],
    }


def get_key():
    value = os.environ.get("VALIDATED_KEY_HEX", "").strip()
    if not value:
        raise ValueError("VALIDATED_KEY_HEX is missing; the previously validated key was not provided to this execution")
    try:
        return bytes.fromhex(value)
    except ValueError as exc:
        raise ValueError("VALIDATED_KEY_HEX is not valid hexadecimal") from exc


def main():
    report = {"endpoint": BASE, "responses": {}, "ciphertext_association": {},
              "source_convention": {}, "decryption": {"performed": False, "padding_valid": False}}
    notes = fetch("/show_encrypted_notes")
    source_response = fetch("/source")
    report["responses"] = {
        "show_encrypted_notes": response_evidence(notes),
        "source": response_evidence(source_response),
    }
    try:
        for label, item in (("show_encrypted_notes", notes), ("source", source_response)):
            if item["status"] != 200 or not item["content_length_matches"]:
                raise ValueError(label + " response was not a complete HTTP 200 response: " + item["error"])
