        source = "\n".join(parser.parts)
        if not source.strip():
            raise ValueError("Could not extract source text from the fresh /source response")

        ciphertext_text = extract_ciphertext(notes_text)
        ciphertext, encoding = decode_ciphertext(ciphertext_text, source)
