            "label": "encrypted_flag",
            "route": "/show_encrypted_notes",
            "encoding": encoding,
            "encoded_length": len(ciphertext_text),
            "ciphertext_bytes": len(ciphertext),
        }
        convention = inspect_padding_convention(source)
        report["source_convention"] = convention
        if not convention["block_size_64_supported"] or not convention["pkcs7_supported"]:
            raise ValueError("Fresh /source evidence does not establish the required 64-byte PKCS#7 padding convention")
        if not convention["xor_operator_present"]:
            raise ValueError("Fresh source does not establish the XOR operation required by this standard-library decryptor")

        key = get_key()
        if len(key) != 64:
            raise ValueError("Previously validated key must be 64 bytes for the observed 64-byte XOR operation")
        if len(ciphertext) != 64:
            raise ValueError("Ciphertext length is not one 64-byte block; refusing unsupported decryption shape")
        plaintext = bytes(ciphertext[i] ^ key[i] for i in range(len(ciphertext)))
        report["decryption"] = {"performed": True, "key_source": "VALIDATED_KEY_HEX environment variable",
                                "key_bytes": len(key), "plaintext_bytes": len(plaintext),
                                "padding_valid": False}
        pad_len = plaintext[-1]
        if pad_len < 1 or pad_len > 64:
            raise ValueError("Decrypted final byte is outside the valid PKCS#7 padding-length range")
        expected = bytes([pad_len]) * pad_len
        if plaintext[-pad_len:] != expected:
            raise ValueError("Strict PKCS#7 byte validation failed")
        logical = plaintext[:-pad_len]
        if not logical:
            raise ValueError("Unpadded logical value is empty")
        report["decryption"]["padding_valid"] = True
        report["decryption"]["padding_length"] = pad_len
        report["decryption"]["logical_value_bytes"] = len(logical)
        report["success"] = True
        print(json.dumps(report, ensure_ascii=False), file=sys.stderr)
        sys.stdout.write(logical.decode("utf-8", errors="strict") + "\n")
        return 0
    except Exception as exc:
        report["success"] = False
        report["error"] = str(exc)
        print(json.dumps(report, ensure_ascii=False))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

