import base64
import json
import os
import re
import sys
import urllib.error
import urllib.request
import xml.etree.ElementTree as ET

HOST = "192.168.4.1"
PATHS = ("/show_encrypted_notes", "/source")
TIMEOUT = 8


def emit(obj):
    print(json.dumps(obj, ensure_ascii=False, sort_keys=True))


def collect_strings(value):
    """Yield strings found in a run_tool envelope, including nested raw output."""
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from collect_strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from collect_strings(item)


def discover_http_ports():
    try:
        import framework_evidence
    except Exception as exc:
        raise RuntimeError("framework_evidence helper is unavailable: " + str(exc))

    envelope = framework_evidence.run_tool(["nmap", "-sV", "-p-", "-oX", "-", HOST])
    print(json.dumps(envelope, ensure_ascii=False, sort_keys=True))
    ports = set()
    for raw in collect_strings(envelope):
        if "<nmaprun" not in raw:
            continue
        try:
            root = ET.fromstring(raw[raw.find("<nmaprun"):])
        except ET.ParseError:
            continue
        for port in root.findall(".//port[@protocol='tcp']"):
            state = port.find("state")
            if state is None or state.get("state") != "open":
                continue
            service = port.find("service")
            name = (service.get("name", "") if service is not None else "").lower()
            tunnel = (service.get("tunnel", "") if service is not None else "").lower()
            product = (service.get("product", "") if service is not None else "").lower()
            if any(token in name + " " + tunnel + " " + product
                   for token in ("http", "https", "ssl", "apache", "nginx", "web")):
                ports.add((int(port.get("portid")), tunnel == "ssl" or "https" in name))
    if not ports:
        raise RuntimeError("No open HTTP/HTTPS-like TCP service was identified in the nmap XML output.")
    return sorted(ports)


def get_body(url):
    request = urllib.request.Request(url, headers={"User-Agent": "evidence-retrieval/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT) as response:
            body = response.read()
            complete = response.length is None or len(body) == response.length
            return {"url": url, "status": response.status, "headers": dict(response.headers),
                    "body": body.decode("utf-8", errors="replace"),
                    "body_bytes": len(body), "complete": complete}
    except urllib.error.HTTPError as exc:
        body = exc.read()
        return {"url": url, "status": exc.code, "headers": dict(exc.headers or {}),
                "body": body.decode("utf-8", errors="replace"),
                "body_bytes": len(body), "complete": True, "http_error": str(exc)}


def find_labeled_ciphertext(text):
    try:
        parsed = json.loads(text)
    except (ValueError, TypeError):
        parsed = None

    def walk(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == "encrypted_flag" and isinstance(value, (str, list)):
                    return value
                found = walk(value)
                if found is not None:
                    return found
        elif isinstance(obj, list):
            for item in obj:
                found = walk(item)
                if found is not None:
                    return found
        return None

    value = walk(parsed) if parsed is not None else None
    if value is None:
        match = re.search(r"encrypted_flag\s*[:=]\s*[\"']?([A-Za-z0-9_+/=-]+)", text)
        if match:
            value = match.group(1)
    if isinstance(value, list) and all(isinstance(x, int) and 0 <= x <= 255 for x in value):
        return bytes(value), "JSON byte array"
    if not isinstance(value, str):
        raise ValueError("Could not identify a ciphertext explicitly labeled encrypted_flag")
    candidate = value.strip()
    try:
        if re.fullmatch(r"(?:[0-9a-fA-F]{2})+", candidate):
            return bytes.fromhex(candidate), "hex"
        return base64.b64decode(candidate, validate=True), "base64"
    except (ValueError, base64.binascii.Error) as exc:
        raise ValueError("Labeled ciphertext is not valid hex or strict base64: " + str(exc))


def get_key():
    raw = os.environ.get("VALIDATED_XOR_KEY_HEX", "").strip()
    if not raw:
        raise ValueError("VALIDATED_XOR_KEY_HEX is absent; cannot apply the previously validated XOR key")
    try:
        key = bytes.fromhex(raw)
    except ValueError as exc:
        raise ValueError("VALIDATED_XOR_KEY_HEX is not valid hexadecimal: " + str(exc))
    if not key:
        raise ValueError("The supplied validated XOR key is empty")
    return key


def main():
    ports = discover_http_ports()
    responses = {}
    errors = []
    for port, tls in ports:
        scheme = "https" if tls else "http"
        for path in PATHS:
            url = "%s://%s:%d%s" % (scheme, HOST, port, path)
            try:
                response = get_body(url)
                # Retain complete response body and response metadata in observable output.
                emit({"type": "http_response", **response})
                if response.get("status") == 200 and response.get("complete"):
                    responses[path] = response
            except Exception as exc:
                errors.append({"url": url, "error": str(exc)})
    if errors:
        emit({"type": "request_errors", "errors": errors})
    if any(path not in responses for path in PATHS):
        raise RuntimeError("Both complete HTTP 200 route responses were not obtained")

    notes = responses["/show_encrypted_notes"]["body"]
    source = responses["/source"]["body"]
    ciphertext, encoding = find_labeled_ciphertext(notes)
    if len(ciphertext) != 64:
        raise ValueError("The labeled ciphertext is %d bytes, not the expected 64 bytes" % len(ciphertext))
    block_match = re.search(r"64\s*[- ]?byte|block.{0,30}64|64.{0,30}block", source, re.I | re.S)
    pkcs_match = re.search(r"PKCS\s*#?7|pkcs7", source, re.I)
    if not block_match or not pkcs_match:
        raise ValueError("Fresh source response did not establish both 64-byte blocks and PKCS#7 padding")

    key = get_key()
    recovered = bytes(byte ^ key[i % len(key)] for i, byte in enumerate(ciphertext))
    if len(recovered) % 64:
        raise ValueError("Recovered plaintext length is not a multiple of the disclosed 64-byte block size")
    pad_length = recovered[-1]
    if not 1 <= pad_length <= 64:
        raise ValueError("Invalid PKCS#7 pad length byte: %d" % pad_length)
    if recovered[-pad_length:] != bytes([pad_length]) * pad_length:
        raise ValueError("Strict byte-level PKCS#7 padding validation failed")
    logical = recovered[:-pad_length]
    try:
        flag = logical.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise ValueError("Unpadded value is not valid UTF-8: " + str(exc))

    emit({"type": "decryption_evidence", "ciphertext_associated_with": "encrypted_flag",
          "ciphertext_encoding": encoding, "ciphertext_bytes": len(ciphertext),
          "key_source": "VALIDATED_XOR_KEY_HEX runtime input",
          "xor_applied": True, "source_discloses_block_bytes": 64,
          "source_discloses_pkcs7": True, "recovered_bytes_hex": recovered.hex(),
          "padding_length": pad_length, "padding_bytes_valid": True,
          "unpadded_value": flag, "standalone_value_emitted_next": True})
    print(flag)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        emit({"type": "result_error", "error": str(exc), "success": False})
        sys.exit(1)

