import base64
import json
import os
import re
import sys
import urllib.error
import urllib.request

BASE = "http://192.168.4.1:8080"
TIMEOUT = 20


def fetch(path):
    url = BASE + path
    req = urllib.request.Request(url, headers={"Accept": "application/json, text/plain, */*"})
    try:
        response = urllib.request.urlopen(req, timeout=TIMEOUT)
    except urllib.error.HTTPError as exc:
        response = exc
    except Exception as exc:
        return {"url": url, "complete": False, "error": repr(exc)}
    try:
        status = response.status
        headers = dict(response.headers.items())
        body = response.read()
        expected = headers.get("Content-Length") or headers.get("content-length")
        length_matches = expected is None or (expected.isdigit() and len(body) == int(expected))
        text = body.decode("utf-8", errors="replace")
        try:
            parsed = json.loads(text)
            parse_status = "json"
        except Exception:
            parsed = None
            parse_status = "non_json_text"
        return {
            "url": url,
            "status": status,
            "headers": headers,
            "body_bytes_length": len(body),
            "body_text": text,
            "parse_status": parse_status,
            "parsed_json": parsed,
            "complete": bool(200 <= status < 300 and length_matches),
            "content_length_matches": length_matches,
            "read_to_eof": True,
        }
    except Exception as exc:
        return {"url": url, "complete": False, "error": "response read failed: " + repr(exc)}
    finally:
        try:
            response.close()
        except Exception:
            pass


def find_labeled_value(obj):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if str(key).lower() == "encrypted_flag":
                return value
        for value in obj.values():
            found = find_labeled_value(value)
            if found is not None:
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = find_labeled_value(value)
            if found is not None:
                return found
    return None


def extract_ciphertext(response):
    parsed = response.get("parsed_json")
    value = find_labeled_value(parsed) if parsed is not None else None
    if value is None:
        text = response.get("body_text", "")
        match = re.search(r"(?is)\bencrypted_flag\b\s*[:=]\s*[\"']([^\"']+)[\"']", text)
        if match:
            value = match.group(1).strip()
    if not isinstance(value, str) or not value.strip():
        return None, "no non-empty encrypted_flag value was parsed"
    value = value.strip()
    try:
        if value.lower().startswith("hex:"):
            raw = bytes.fromhex(value[4:].strip())
            encoding = "hex prefix"
        elif value.lower().startswith("base64:"):
            raw = base64.b64decode(value[7:].strip(), validate=True)
            encoding = "base64 prefix"
        elif re.fullmatch(r"(?:0x)?[0-9a-fA-F]+", value) and len(value.removeprefix("0x")) % 2 == 0:
            raw = bytes.fromhex(value.removeprefix("0x"))
            encoding = "bare hex"
        else:
            raw = base64.b64decode(value, validate=True)
            encoding = "bare base64"
        if not raw:
            return None, "ciphertext decoded to empty bytes"
        return raw, encoding
    except Exception as exc:
        return None, "ciphertext encoding could not be decoded: " + repr(exc)


def source_padding_evidence(text):
    block_patterns = (
        r"(?i)block(?:_size|\s+size)?\s*(?:=|:|is)?\s*64\b",
        r"(?i)64\s*[- ]byte\s+blocks?",
        r"(?i)blocks?\s+of\s+64\s+bytes",
    )
    has_block = any(re.search(pattern, text) for pattern in block_patterns)
    has_pkcs7 = bool(re.search(r"(?i)pkcs\s*[-_]?\s*7", text))
    return has_block, has_pkcs7


def main():
    notes = fetch("/show_encrypted_notes")
    source = fetch("/source")
    evidence = {
        "purpose": "Fresh targeted retrieval and strict XOR/PKCS#7 verification; no discovery scan performed.",
        "responses": {"/show_encrypted_notes": notes, "/source": source},
        "ciphertext_association": "not established",
        "ciphertext_encoding": None,
        "padding_evidence": None,
        "key_evidence": None,
        "decryption": None,
        "success": False,
        "gaps": [],
    }
    if not notes.get("complete"):
        evidence["gaps"].append("/show_encrypted_notes response was not confirmed complete and successful")
    if not source.get("complete"):
        evidence["gaps"].append("/source response was not confirmed complete and successful")

    ciphertext = None
    if notes.get("complete"):
        ciphertext, enc_or_error = extract_ciphertext(notes)
        if ciphertext is None:
            evidence["gaps"].append(enc_or_error)
        else:
            evidence["ciphertext_association"] = "parsed from the notes response field encrypted_flag"
            evidence["ciphertext_encoding"] = enc_or_error
            evidence["ciphertext_bytes_length"] = len(ciphertext)

    has_block = has_pkcs7 = False
    if source.get("complete"):
        has_block, has_pkcs7 = source_padding_evidence(source.get("body_text", ""))
        evidence["padding_evidence"] = {
            "64_byte_block_convention_found": has_block,
            "PKCS7_convention_found": has_pkcs7,
        }
        if not has_block or not has_pkcs7:
            evidence["gaps"].append("complete /source response did not establish both 64-byte blocks and PKCS#7 padding")

    key_hex = os.environ.get("VALIDATED_XOR_KEY_HEX", "").strip()
    key = None
    if not key_hex:
        evidence["key_evidence"] = "VALIDATED_XOR_KEY_HEX is not present; the validated key bytes were not supplied to this action"
        evidence["gaps"].append("previously validated XOR key value is unavailable to this action")
    else:
        try:
            key = bytes.fromhex(key_hex.removeprefix("0x"))
            if not key:
                raise ValueError("empty key")
            evidence["key_evidence"] = {
                "source": "runtime environment variable VALIDATED_XOR_KEY_HEX",
                "bytes_length": len(key),
                "key_value_exposed": False,
            }
        except Exception as exc:
            evidence["key_evidence"] = "invalid VALIDATED_XOR_KEY_HEX: " + repr(exc)
            evidence["gaps"].append("runtime XOR key value was not valid non-empty hexadecimal")

    if ciphertext is not None and key is not None and notes.get("complete") and source.get("complete") and has_block and has_pkcs7:
        plaintext = bytes(byte ^ key[i % len(key)] for i, byte in enumerate(ciphertext))
        result = {"plaintext_bytes_length": len(plaintext), "block_aligned": len(plaintext) % 64 == 0}
        if len(plaintext) % 64 == 0 and plaintext:
            pad = plaintext[-1]
            valid_padding = 1 <= pad <= 64 and plaintext[-pad:] == bytes([pad]) * pad
        else:
            pad = None
            valid_padding = False
        result["padding_byte_value"] = pad
        result["strict_pkcs7_padding_valid"] = valid_padding
        if valid_padding:
            unpadded = plaintext[:-pad]
            try:
                flag = unpadded.decode("utf-8", errors="strict")
                result["unpadded_utf8_valid"] = True
                result["unpadded_byte_length"] = len(unpadded)
                evidence["decryption"] = result
                evidence["success"] = True
            except UnicodeDecodeError as exc:
                result["unpadded_utf8_valid"] = False
                result["error"] = repr(exc)
                evidence["decryption"] = result
                evidence["gaps"].append("strictly unpadded bytes were not valid UTF-8")
        else:
            evidence["decryption"] = result
            evidence["gaps"].append("decrypted bytes failed strict 64-byte-block PKCS#7 validation")
    else:
        evidence["decryption"] = "not attempted because required complete response, ciphertext, padding, or key evidence is missing"

    print(json.dumps(evidence, ensure_ascii=False), file=sys.stderr, flush=True)
    if evidence["success"]:
        print(flag, flush=True)


if __name__ == "__main__":
    main()

