import json
import re
import urllib.error
import urllib.request

BASE = "http://192.168.4.1:8080"
ROUTES = ("/show_encrypted_notes", "/source")


def fetch(path):
    url = BASE + path
    request = urllib.request.Request(url, headers={"User-Agent": "targeted-evidence-retrieval/1.0"})
    result = {
        "url": url,
        "http_status": None,
        "headers": {},
        "body": "",
        "body_parse": "not_attempted",
        "completeness": "unknown",
    }
    response = None
    try:
        response = urllib.request.urlopen(request, timeout=20)
    except urllib.error.HTTPError as exc:
        response = exc
    except Exception as exc:
        result["request_error"] = f"{type(exc).__name__}: {exc}"
        return result

    try:
        result["http_status"] = getattr(response, "status", None)
        result["headers"] = dict(response.headers.items())
        expected = response.headers.get("Content-Length")
        body = response.read()
        result["body"] = body.decode("utf-8", errors="replace")
        result["body_parse"] = "read_to_end"
        if expected is not None:
            try:
                result["completeness"] = "complete" if len(body) == int(expected) else "incomplete_content_length_mismatch"
                result["content_length_expected"] = int(expected)
                result["content_length_received"] = len(body)
            except ValueError:
                result["completeness"] = "unknown_invalid_content_length"
        else:
            result["completeness"] = "read_to_end_no_content_length"
    except Exception as exc:
        result["body_parse"] = "read_error"
        result["read_error"] = f"{type(exc).__name__}: {exc}"
    finally:
        response.close()
    return result


def find_labeled_ciphertext(body):
    try:
        parsed = json.loads(body)
    except Exception:
        parsed = None

    def search(value):
        if isinstance(value, dict):
            for key, item in value.items():
                if str(key).strip().lower() == "encrypted_flag" and isinstance(item, (str, int)):
                    return str(item)
                found = search(item)
                if found is not None:
                    return found
        elif isinstance(value, list):
            for item in value:
                found = search(item)
                if found is not None:
                    return found
        return None

    found = search(parsed) if parsed is not None else None
    if found is not None:
        return {"parser": "json", "value": found, "nonempty": bool(found.strip())}

    match = re.search(
        r"encrypted_flag\s*[=:]\s*[\"']?([^\"'\s,;}]+)", body, re.IGNORECASE
    )
    if match:
        value = match.group(1)
        return {"parser": "text_pattern", "value": value, "nonempty": bool(value.strip())}
    return {"parser": "not_found", "value": None, "nonempty": False}


observations = {path: fetch(path) for path in ROUTES}
notes = observations["/show_encrypted_notes"]
source = observations["/source"]

ciphertext = find_labeled_ciphertext(notes.get("body", ""))
source_text = source.get("body", "")
block_evidence = re.findall(r".{0,60}64\s*[- ]?byte\s+blocks?.{0,100}", source_text, re.IGNORECASE | re.DOTALL)
padding_evidence = re.findall(r".{0,80}(?:PKCS\s*#?7|PKCS7|padding).{0,120}", source_text, re.IGNORECASE | re.DOTALL)

output = {
    "purpose": "Fresh targeted retrieval of the two identified routes; no discovery performed.",
    "route_observations": observations,
    "encrypted_flag_association": {
        "response_route": "/show_encrypted_notes",
        **ciphertext,
    },
    "service_format_evidence": {
        "block_size_snippets": block_evidence,
        "padding_snippets": padding_evidence,
        "raw_source_response_retained": True,
    },
    "validated_key_use": "not_attempted_key_value_not_available_in_supplied_input",
    "decryption": "not_attempted",
    "strict_padding_validation": "not_attempted",
    "standalone_flag_emitted": False,
    "limitation": "The supplied prior-evidence preview says a validated key exists but does not include its value. No key is fabricated or inferred here.",
}
print(json.dumps(output, ensure_ascii=False))

